import React from 'react';

const Footer = () => {
  const styles = {
    footer: { background: '#ffffff', padding: '60px 24px 24px', borderTop: '1px solid #f0f0f0', fontFamily: 'Poppins, sans-serif' },
    container: { maxWidth: 1200, margin: '0 auto', display: 'flex', justifyContent: 'space-between', flexWrap: 'wrap', gap: 40 },
    col: { flex: '1 1 250px', display: 'flex', flexDirection: 'column', gap: 16 },
    logoArea: { display: 'flex', alignItems: 'center', gap: 10 },
    logoImg: { height: 32, width: 'auto', objectFit: 'contain' },
    logoText: { fontSize: 18, fontWeight: 700, color: '#111' },
    desc: { fontSize: 13.5, color: '#666', lineHeight: 1.6 },
    list: { listStyle: 'none', padding: 0, margin: 0, display: 'flex', flexDirection: 'column', gap: 10, fontSize: 13.5, color: '#555' },
    bottom: { borderTop: '1px solid #f5f5f5', marginTop: 50, paddingTop: 24, width: '100%' },
    // Copyright parfaitement centré à 100%
    copyright: { fontSize: 13, color: '#999', textAlign: 'center', width: '100%', margin: 0 }
  };

  return (
    <style.footer style={styles.footer}>
      <div style={styles.container}>
        <div style={styles.col}>
          <div style={styles.logoArea}>
            <img src="/djamano.png" alt="Djamano Logo" style={styles.logoImg} />
            <span style={styles.logoText}>Djamano</span>
          </div>
          <p style={styles.desc}>La solution idéale pour dynamiser et sécuriser l'organisation de tous vos événements.</p>
        </div>

        <div style={styles.col}>
          <h4 style={{ fontSize: 15, fontWeight: 700, color: '#111' }}>Contact</h4>
          <ul style={styles.list}>
            <li>+226 79 63 25 45</li>
            <li>djamanoinfo01@gmail.com</li>
            <li>Ouagadougou, Burkina Faso</li> {/* "Koulouba" a été retiré ici */}
          </ul>
        </div>

        <div style={styles.bottom}>
          {/* Centrage parfait du texte de copyright */}
          <p style={styles.copyright}>
            © 2026 Djamano. Tous droits réservés.
          </p>
        </div>
      </div>
    </style.footer>
  );
};

export default Footer;
